using Orchestration.API.Engineering.Contracts;namespace Orchestration.API.Engineering.Federation;
public interface IFederatedExtractionStatusAggregator{StandardStatus Aggregate(IReadOnlyList<StandardStatus> values,bool cancellationRequested);}
public sealed class FederatedExtractionStatusAggregator:IFederatedExtractionStatusAggregator{public StandardStatus Aggregate(IReadOnlyList<StandardStatus> v,bool cancelled){if(cancelled)return StandardStatus.Cancelled;if(v.Count==0)return StandardStatus.Empty;var usable=v.Any(x=>x is StandardStatus.Success or StandardStatus.PartialSuccess);if(usable)return v.All(x=>x==StandardStatus.Success)?StandardStatus.Success:StandardStatus.PartialSuccess;if(v.All(x=>x==StandardStatus.Empty))return StandardStatus.Empty;if(v.All(x=>x==StandardStatus.Unavailable))return StandardStatus.Unavailable;if(v.Any(x=>x==StandardStatus.AwaitingContext))return StandardStatus.AwaitingContext;if(v.All(x=>x==StandardStatus.TimedOut))return StandardStatus.TimedOut;if(v.All(x=>x==StandardStatus.Cancelled))return StandardStatus.Cancelled;return StandardStatus.Failed;}}
